INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قمر:lane_lexicon', 'قمر', '338a8c4b9502e790ab4df09871', 'became dazzled (Ṣ, A, Ḳ) in the moonlight, (A,) or by snow, (Ṣ, A, Ḳ,) so that he could not see', 'eyes dazzled by moonlight or snow', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_2908549e59ccf249', '2562', NULL, 'blk_lane_0bda551d84f55831', 0, NULL, 'Marker: first sense A1. Reading: dazzled eyes. Differs from the main reading (whiteness).', 'medium', 'active');
