INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قمص:khalil_kitab_ayn', 'قمص', '75b68812371e24e8dd640237b0', 'القِماصُ: ألا يستقر في موضع، تراه يقمِص فيثب من مكانه من غير صبر', 'not staying put, jumping from its place', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_7a0ade44b7ab65a3', '1642', NULL, 'blk_kay_0f2845ebaea1ea5a', 0, NULL, 'Marker: head gloss. Reading: restless jumping. Primary: leaping about — 7 of 10 books (al-Khalīl blk_kay_0f2845ebaea1ea5a; Ibn Durayd blk_jam_498b56176c795ffa; al-Jawharī blk_sih_f27d9052b6595a43; Ibn Fāris blk_mqy_a3d3825563065df6; al-Qāmūs blk_qms_fc49e595a9d65758; Tāj blk_taj_96c6313b529d0fd9; Lane blk_lane_f15528b6c2c721ab). Other readings: putting on a shirt: Ibn Fāris, al-Rāghib, Lisān, al-Miṣbāḥ.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قمص:ibn_durayd_jamharat_lugha', 'قمص', '75b68812371e24e8dd640237b0', 'قَمَصَ البعيرُ يقمُص ويقمِص قَمْصاً وقُماصاً، وَهُوَ أَن يرفع يَدَيْهِ ثمَّ يطرحهما مَعًا', 'camel lifts forelegs and drops them together', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_bba2a268773c7a27', '540', NULL, 'blk_jam_498b56176c795ffa', 0, NULL, 'Marker: head gloss. Reading: bucking.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قمص:jawhari_sihah', 'قمص', '75b68812371e24e8dd640237b0', 'قَمَصَ الفرسُ وغيره يَقْمُص ويَقْمِصُ قَمْصاً وقُماصاً، أي اسْتَنَّ، وهو أن يرفع يديه ويطرحهما معاً', 'horse lifts forelegs and drops them together', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_58ca8a5da51d48f3', '2089', 3, 'blk_sih_f27d9052b6595a43', 0, NULL, 'Marker: head gloss. Reading: bucking.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قمص:raghib_mufradat', 'قمص', '75b68812371e24e8dd640237b0', 'الْقَمِيصُ معروف، وجمعه قُمُصٌ وأَقْمِصَةٌ وقُمْصَانٌ', 'the shirt, a known thing', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_9645c8002c71dd75', '684', 1, 'blk_mfr_afff6cfd111a2527', 0, NULL, 'Marker: head definition. Reading: shirt. Differs from the main reading (leaping about).', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قمص:ibn_manzur_lisan_arab', 'قمص', '75b68812371e24e8dd640237b0', 'الْقَمِيصُ الَّذِي يُلْبَسُ مَعْرُوفٌ مُذَكَّرٌ', 'the shirt one wears', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_81ce29560c9c2d1a', '3465', 7, 'blk_lsn_073f8c40579b648b', 0, NULL, 'Marker: head gloss. Reading: shirt. Differs from the main reading (leaping about).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قمص:fayyumi_misbah_munir', 'قمص', '75b68812371e24e8dd640237b0', 'الْقَمِيصُ جَمْعُهُ قُمْصَانٌ وَقُمُصٌ بِضَمَّتَيْنِ وَقَمَّصْتُهُ قَمِيصًا بِالتَّشْدِيدِ أَلْبَسْتُهُ فَتَقَمَّصَهُ', 'shirt; I dressed him in a shirt', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_377dfbc3c626c116', '2540', NULL, 'blk_msb_9c47ee4619410bd5', 0, NULL, 'Marker: head gloss. Reading: shirt. Differs from the main reading (leaping about).', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قمص:qamus_muhit', 'قمص', '75b68812371e24e8dd640237b0', 'قَمَصَ الفرسُ وغيرُه يَقْمُصُ ويَقْمِصُ قَمْصاً وقُمَاصاً، بالضم الكسرِ، أو إذا صارَ عادةً له، فبالضم: وهو أن يَرْفَعَ يَدَيهِ ويَطْرَحَهُما مَعاً', 'horse lifts forelegs and drops them together', 'الفيروزآبادي', 'al-Fīrūzābādī, al-Qāmūs', 817, 'qamus_muhit', 're_qms_9035f6cf3d4f71f2', NULL, NULL, 'blk_qms_fc49e595a9d65758', 0, NULL, 'Marker: Qāmūs gloss. Reading: bucking.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قمص:zabidi_taj_arus', 'قمص', '75b68812371e24e8dd640237b0', 'وهُوَ أَي القَمْصُ والقُمَاصُ أَنْ يَرْفَعَ يَدَيْهِ ويَطْرَحَهُمَا مَعاً، ويَعْجِنَ برِجْلَيْهِ', 'lifting forelegs together, kicking with hind legs', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_e64eaf8902427c84', '126', 18, 'blk_taj_96c6313b529d0fd9', 0, NULL, 'Marker: Qāmūs gloss. Reading: bucking.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قمص:lane_lexicon', 'قمص', '75b68812371e24e8dd640237b0', 'He (a horse or other animal, Ṣ, A, Ḳ, or a camel, Mṣb) raised his fore legs together and put them down together', 'animal raised forelegs and put them down', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_57ba5d71e9a5e6f1', '2563', NULL, 'blk_lane_f15528b6c2c721ab', 0, NULL, 'Marker: first sense A1. Reading: bucking.', 'high', 'active');
