INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قمع:khalil_kitab_ayn', 'قمع', '02dc7346697275fb0ee38dcb43', 'قَمَعْتُ فُلاناً فانْقَمَعَ: أي ذَلَّلْتُه فذَلَّ واخْتَبَأَ فَرَقاً', 'I humbled him; he gave in and hid', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_39a4e478993ba755', '178', NULL, 'blk_kay_a6f2b9357bdad15c', 0, NULL, 'Marker: head gloss. Reading: humbling. Primary: humbling — 8 of 9 books (al-Khalīl blk_kay_a6f2b9357bdad15c; Ibn Durayd blk_jam_6845c573e1e710df; al-Jawharī blk_sih_27f64fc25557e126; Ibn Fāris blk_mqy_06df292af0d69e50; al-Rāghib blk_mfr_9661454f51b5f09f; Lisān blk_lsn_cd1c5b8f7442321d; al-Miṣbāḥ blk_msb_377c0325d31d0467; Tāj blk_taj_1117410a863ce9c6). Other readings: cap of a fruit: Lane · pouring through a funnel: Ibn Fāris · a kind of animal: Ibn Fāris.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قمع:ibn_durayd_jamharat_lugha', 'قمع', '02dc7346697275fb0ee38dcb43', 'وقَمَعْتُ الرجلَ أقمَعه قَمْعاً، إِذا ضربت رأسَه فانقمع، أَي فذلّ', 'hit his head so he gave in', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_bba2a268773c7a27', '540', NULL, 'blk_jam_6845c573e1e710df', 0, NULL, 'Marker: «إذا» gloss. Reading: beating down.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قمع:jawhari_sihah', 'قمع', '02dc7346697275fb0ee38dcb43', 'وقَمَعْتُهُ وأقْمَعْتُهُ بمعنًى، أي قهرته وأذللته، فانْقَمَعَ', 'I overpowered and humbled him', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_2b116c1819a5b32a', '2521', 3, 'blk_sih_27f64fc25557e126', 0, NULL, 'Marker: verb gloss «أي». Reading: humbling.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قمع:raghib_mufradat', 'قمع', '02dc7346697275fb0ee38dcb43', 'جمع مِقْمَعٍ، وهو ما يضرب به ويذلّل، ولذلك يقال: قَمَعْتُهُ فَانْقَمَعَ، أي: كففته فكفّ', 'a club to beat and humble with', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_c78878959e2a197b', '684', 1, 'blk_mfr_9661454f51b5f09f', 0, NULL, 'Marker: head definition. Reading: humbling.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قمع:ibn_manzur_lisan_arab', 'قمع', '02dc7346697275fb0ee38dcb43', 'قَمَعَ الرجلَ يَقْمَعُه قَمْعاً وأَقْمَعَه فانْقَمَعَ قَهَرَه وذَلَّلَه فذَلَّ', 'overpowered and humbled him, so he gave in', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_53e492e41f9821b2', '4142', 8, 'blk_lsn_cd1c5b8f7442321d', 0, NULL, 'Marker: head gloss. Reading: humbling.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قمع:fayyumi_misbah_munir', 'قمع', '02dc7346697275fb0ee38dcb43', 'قَمَعْتُهُ قَمْعًا أَذْلَلْتُهُ', 'I humbled him', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_8f3c3a427d180fb1', '2543', NULL, 'blk_msb_377c0325d31d0467', 0, NULL, 'Marker: head gloss. Reading: humbling.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قمع:zabidi_taj_arus', 'قمع', '02dc7346697275fb0ee38dcb43', 'وقَمَعَهُ قَمْعاً: قَهَرَهُ، وذَلَّلَهُ، كأقْمَعَهُ إقْماعاً، فانْقَمَعَ', 'overpowered and humbled him', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_5adc9613f84aa1c3', '75', 22, 'blk_taj_1117410a863ce9c6', 0, NULL, 'Marker: Qāmūs gloss. Reading: humbling.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قمع:lane_lexicon', 'قمع', '02dc7346697275fb0ee38dcb43', 'قَمِعُ البُسْرِ What sticks to the date, around its stalk: (Mgh:) the base of the date.', 'the cap on a date at its stalk', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_0d7f5043e0712d1e', '2993', NULL, 'blk_lane_eee08ca10f0c5637', 0, NULL, 'Marker: first noun sense. Reading: date cap. Differs from the main reading (humbling).', 'medium', 'active');
