INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قوع:jawhari_sihah', 'قوع', '630dc57772579a498c39c0169f', 'قاعَ الفحلُ على الناقة يَقوعُ قَوْعاً وقِياعاً، إذا نزا', 'the stallion mounted the she-camel', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_8c1e3a777c0bda81', '2526', 3, 'blk_sih_4798c14caccc4d82', 0, NULL, 'Marker: head gloss. Reading: stallion mounting. Primary: stallion mounting — 3 of 6 books (al-Jawharī blk_sih_4798c14caccc4d82; Lisān blk_lsn_59850b0cf8abd5b0; Tāj blk_taj_985b22752c05d72d). Other readings: flat open ground: Ibn Fāris, al-Miṣbāḥ, Lane.', 'high', 'active');
