INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قوي:jawhari_sihah', 'قوي', 'df984e52d929893dcbe8114947', 'القُوَّةُ: خلاف الضعف', 'strength, the opposite of weakness', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_a0b54d31089a8535', '4898', 6, 'blk_sih_65fdb0108a6a5e72', 0, NULL, 'Marker: head gloss. Reading: strength. Primary: strength — 7 of 8 books (al-Jawharī blk_sih_65fdb0108a6a5e72; Ibn Fāris blk_mqy_629df970a1a02087; al-Rāghib blk_mfr_d1b8fdc9c97f8d00; Lisān blk_lsn_12a3df3463f873d4; al-Miṣbāḥ blk_msb_6b8fa6e1017f3c58; Tāj blk_taj_fc472ab1f252442c; Lane blk_lane_f89d4afb39b32787). Other readings: rope strand: Ibn Durayd · empty land, little good: Ibn Fāris.', 'high', 'active');
