INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قوي:ibn_manzur_lisan_arab', 'قوي', 'df984e52d929893dcbe8114947', 'ابْنُ سِيدَهْ: القُوَّةُ نَقِيضُ الضَّعْفِ، وَالْجَمْعُ قُوًى وقِوًى', 'strength, the opposite of weakness', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_de149649e791759e', '7817', 15, 'blk_lsn_12a3df3463f873d4', 0, NULL, 'Marker: head gloss. Reading: strength. Quoted from Ibn Sīdah via Lisān.', 'high', 'active');
