INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:كثب:zabidi_taj_arus', 'كثب', 'ec4d9c49a04e0edca9efbce1e2', 'الكَثْبُ: الجَمْعُ) من قُرْبٍ', 'gathering from close by', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_cf0469d711df0504', '107', 4, 'blk_taj_7532357729af3271', 0, NULL, 'Marker: Qāmūs gloss. Reading: gathering.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:كثب:lane_lexicon', 'كثب', 'ec4d9c49a04e0edca9efbce1e2', 'He collected it together, (Ṣ, Ḳ,) from a near place.', 'he gathered it from close by', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_0d658053ca820c97', '2592', NULL, 'blk_lane_1f0947abd6769e25', 0, NULL, 'Marker: first sense A1. Reading: gathering.', 'high', 'active');
UPDATE ar_ling_root_asl SET note_md = trim(CASE WHEN instr(coalesce(note_md,''),'Primary:') > 0 THEN substr(note_md, 1, instr(note_md,'Primary:') - 1) ELSE coalesce(note_md,'') END) || ' ' || 'Reading: gathering.', updated_at = datetime('now') WHERE id = 'ASL:كثب:maqayis_lugha' AND coalesce(note_md,'') NOT LIKE '%Reading:%';
UPDATE ar_ling_root_asl SET is_primary = CASE WHEN id = 'ASL:كثب:ibn_durayd_jamharat_lugha' THEN 1 ELSE 0 END, updated_at = datetime('now') WHERE root_norm = 'كثب' AND EXISTS (SELECT 1 FROM ar_ling_root_asl WHERE id = 'ASL:كثب:ibn_durayd_jamharat_lugha' AND status <> 'rejected');
